// PARSE the canonical `s("<cat>", "<id>", …)` call sites out of the category files the
// manifest imports (`demo/stories/manifest/categories/<id>.ts`). Route paths are
// `/${category}/${story}` (demo/router.ts buildRoutes). If a story id/category is
// renamed in the manifest, this re-source tracks it — there is no second hand-list
// to drift.

// The rows live one file per category; the manifest's own imports name those files,
// so a category file the manifest does not assemble is not a scene either.
const manifest = readFileSync(MANIFEST_PATH, "utf8");
const rowFiles = [
    ...manifest.matchAll(/from "\.\/(manifest\/categories\/[a-z0-9-]+)"/g),
].map((m) => `${LIBRARY_ROOT}demo/stories/${m[1]!}.ts`);
if (rowFiles.length === 0) {
    throw new Error(
        `pi-manifest: re-source FAILED — ${MANIFEST_PATH} imports no ./manifest/categories/<id> row file. The manifest's assembly moved; the SCENES re-source is the source-of-truth, do NOT hand-list.`,
    );
}
const src = rowFiles.map((file) => readFileSync(file, "utf8")).join("\n");
